```java
// Pull Request: Add order validation before payment processing
// Context: Customers were able to submit orders with negative quantities

@Service
public class OrderService {
    private final PaymentGateway paymentGateway;
    private final OrderRepository orderRepository;

    public OrderService(PaymentGateway paymentGateway, OrderRepository orderRepository) {
        this.paymentGateway = paymentGateway;
        this.orderRepository = orderRepository;
    }

    public Order processOrder(OrderRequest request) {
        // Validation added to catch business rule violations early
        if (request.quantity() <= 0) {
            throw new InvalidOrderException("Quantity must be positive");
        }
        if (request.totalAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new InvalidOrderException("Order total must be positive");
        }

        var order = new Order(request.productId(), request.quantity());
        var payment = paymentGateway.charge(request.totalAmount());

        order.setPaymentId(payment.id());
        return orderRepository.save(order);
    }
}
```
A clear PR description plus a small, focused diff like this is exactly what makes a change quick to review.

