        // Error handling: What if orderService throws an exception? (Unhandled)
        // Performance: Is this method doing too much work in the HTTP thread?
        // Readability: Is field injection best practice? (Constructor injection preferred)
        // Tests: Are there integration tests covering this endpoint?

        var order = orderService.createOrder(
            request.productId(),
            request.quantity()
        );

        // Reviewer checks: success should return 201 Created, not 200 OK
        return ResponseEntity.ok(order);
    }
}
